const srcDir = path.join(pkgRoot, 'src');
const i18nDir = path.join(srcDir, 'i18n');

let pass = 0, fail = 0;
const fails = [];
const check = (label, ok) => { if (ok) pass++; else { fail++; fails.push(label); } };

