const css2 = fs.readFileSync(path.join(srcDir, 'renderer', 'renderer.css'), 'utf8');
const selectors = (s) => { const t = s.replace(/\/\*[\s\S]*?\*\//g, ''); const out = new Set(); let m; const re = /([^{}]+)\{/g; while ((m = re.exec(t))) { const head = m[1].trim(); if (!head || head.startsWith('@')) continue; for (const sel of head.split(',')) { const x = sel.trim(); if (x) out.add(x); } } return out; };
const s1 = selectors(css1), s2 = selectors(css2);
const used = new Set([...(appJs + emTs).matchAll(/\b(?:t|tOr|tMain)\(\s*'([a-zA-Z0-9_.]+)'/g)].map((x) => x[1]));
const hooks = new Set([...appJs.matchAll(/window\.(\__\w+)\s*=/g)].map((x) => x[1]));
const chans = new Set([...pre.matchAll(/ipcRenderer\.(?:invoke|send|on)\('([\w:]+)'/g)].map((x) => x[1]));
